import 'package:flutter/material.dart';import '../../services/demo_store.dart';import '../../widgets/party_card.dart';
class HomeScreen extends StatefulWidget{const HomeScreen({super.key});@override State<HomeScreen>createState()=>_HomeScreenState();}class _HomeScreenState extends State<HomeScreen>{final s=DemoStore.instance;@override void initState(){super.initState();s.init();s.addListener(_changed);}@override void dispose(){s.removeListener(_changed);super.dispose();}void _changed(){if(mounted)setState((){});}@override Widget build(BuildContext c)=>SafeArea(child:CustomScrollView(slivers:[SliverAppBar(title:const Text('图趴 PicParty'),floating:true,actions:[IconButton(onPressed:()=>Navigator.pushNamed(c,'/search'),icon:const Icon(Icons.search))]),SliverPadding(padding:const EdgeInsets.all(16),sliver:SliverList(delegate:SliverChildBuilderDelegate((_,i)=>Padding(padding:const EdgeInsets.only(bottom:12),child:PartyCard(party:s.parties[i],onTap:()=>Navigator.pushNamed(c,'/party/${s.parties[i].id}'))),childCount:s.parties.length)))]));}
